"use strict";(self.webpackChunkmcp_ai=self.webpackChunkmcp_ai||[]).push([[9011],{28453:(e,n,t)=>{t.d(n,{R:()=>s,x:()=>r});var i=t(96540);const a={},o=i.createContext(a);function s(e){const n=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:n},e.children)}},47857:e=>{e.exports=JSON.parse('{"permalink":"/milano-software-hapi-mcp-ai-adoption","source":"@site/blog/milano-software-hapi-mcp-ai-adoption.md","title":"Do Not Rebuild a Reliable Platform for AI: How Milano Software Is Accelerating AI Adoption","description":"Milano Software is using HAPI MCP to make reliable enterprise APIs accessible to AI without rebuilding its proven platform, across on-premise, air-gapped, hybrid, and cloud environments.","date":"2026-09-15T22:36:03.000Z","tags":[],"readingTime":12.57,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Do Not Rebuild a Reliable Platform for AI: How Milano Software Is Accelerating AI Adoption","description":"Milano Software is using HAPI MCP to make reliable enterprise APIs accessible to AI without rebuilding its proven platform, across on-premise, air-gapped, hybrid, and cloud environments.","keywords":["HAPI MCP","Milano Software","enterprise MCP","on-premise MCP","air-gapped AI","API to MCP","enterprise AI adoption","Model Context Protocol"],"image":"/img/blog/milano-software-hapi-mcp-ai-adoption.png"},"unlisted":false,"prevItem":{"title":"MCP Elicitation Is a Symptom, Not a Strategy","permalink":"/mcp-elicitation-surfaces-issue-in-your-design"},"nextItem":{"title":"From OpenAPI to MCP to AI Agent: The Zero-Code Playbook","permalink":"/openapi-to-mcp-to-ai-agent"}}')},65716:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>s,metadata:()=>i,toc:()=>d});var i=t(47857),a=t(74848),o=t(28453);const s={title:"Do Not Rebuild a Reliable Platform for AI: How Milano Software Is Accelerating AI Adoption",description:"Milano Software is using HAPI MCP to make reliable enterprise APIs accessible to AI without rebuilding its proven platform, across on-premise, air-gapped, hybrid, and cloud environments.",keywords:["HAPI MCP","Milano Software","enterprise MCP","on-premise MCP","air-gapped AI","API to MCP","enterprise AI adoption","Model Context Protocol"],image:"/img/blog/milano-software-hapi-mcp-ai-adoption.png"},r=void 0,l={authorsImageUrls:[]},d=[{value:"The business lesson: AI adoption should compound previous investments",id:"the-business-lesson-ai-adoption-should-compound-previous-investments",level:2},{value:"What does it mean to make an API &quot;HAPI&quot;?",id:"what-does-it-mean-to-make-an-api-hapi",level:2},{value:"Why not expose every API operation to the agent?",id:"why-not-expose-every-api-operation-to-the-agent",level:2},{value:"How does HAPI MCP reduce the cost and risk of enterprise AI adoption?",id:"how-does-hapi-mcp-reduce-the-cost-and-risk-of-enterprise-ai-adoption",level:2},{value:"1. It protects the investment already made in APIs",id:"1-it-protects-the-investment-already-made-in-apis",level:3},{value:"2. It creates a controlled boundary for AI",id:"2-it-creates-a-controlled-boundary-for-ai",level:3},{value:"3. It supports incremental delivery",id:"3-it-supports-incremental-delivery",level:3},{value:"4. It keeps deployment choices open",id:"4-it-keeps-deployment-choices-open",level:3},{value:"5. It creates an architecture that can evolve",id:"5-it-creates-an-architecture-that-can-evolve",level:3},{value:"Why on-premise and air-gapped AI matter",id:"why-on-premise-and-air-gapped-ai-matter",level:2},{value:"What did Milano Software validate in HAPI MCP 0.8?",id:"what-did-milano-software-validate-in-hapi-mcp-08",level:2},{value:"Where does Clawne Me fit?",id:"where-does-clawne-me-fit",level:2},{value:"What should other API-first companies learn from this collaboration?",id:"what-should-other-api-first-companies-learn-from-this-collaboration",level:2},{value:"Do you need to rebuild your platform to become an AI company?",id:"do-you-need-to-rebuild-your-platform-to-become-an-ai-company",level:3},{value:"Should every endpoint become an MCP tool?",id:"should-every-endpoint-become-an-mcp-tool",level:3},{value:"Is MCP only for public-cloud AI?",id:"is-mcp-only-for-public-cloud-ai",level:3},{value:"Does MCP replace REST or gRPC?",id:"does-mcp-replace-rest-or-grpc",level:3},{value:"What is the best first AI use case?",id:"what-is-the-best-first-ai-use-case",level:3},{value:"The bigger idea: preserve reliability while changing the interface",id:"the-bigger-idea-preserve-reliability-while-changing-the-interface",level:2},{value:"Thank you, Milano Software and Imran",id:"thank-you-milano-software-and-imran",level:2},{value:"Suggested SEO metadata",id:"suggested-seo-metadata",level:2},{value:"Suggested LinkedIn post",id:"suggested-linkedin-post",level:2}];function c(e){const n={a:"a",blockquote:"blockquote",em:"em",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"The expensive part of enterprise AI is often not the model. It is rebuilding what already works."})}),"\n",(0,a.jsx)(n.p,{children:"Many software companies have spent years, and sometimes decades, turning business rules, customer needs, operational lessons, security controls, and hard-won reliability into production APIs."}),"\n",(0,a.jsxs)(n.p,{children:["Then AI arrives, and the first instinct is often: ",(0,a.jsx)(n.em,{children:"We need to rebuild the platform for agents."})]}),"\n",(0,a.jsx)(n.p,{children:"That can be a costly mistake."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://milanosoftware.com",children:"Milano Software"})," is taking a more practical path. Instead of replacing its reliable API platform to make it useful to AI, the company is exploring how to expose selected capabilities through the Model Context Protocol (MCP). HAPI MCP provides the bridge."]}),"\n",(0,a.jsxs)(n.p,{children:["The goal is not to make the APIs obsolete. The goal is to make them ",(0,a.jsx)(n.strong,{children:"HAPI"}),": accessible to AI consumers while preserving the platform, business logic, and deployment model Milano already trusts."]}),"\n",(0,a.jsxs)(n.p,{children:["This collaboration has also been an important source of real-world feedback and validation for HAPI MCP ",(0,a.jsx)(n.em,{children:"version 0.8"}),', especially for enterprise environments where "just deploy it in the public cloud" is not a valid answer.']}),"\n",(0,a.jsx)(n.h2,{id:"the-business-lesson-ai-adoption-should-compound-previous-investments",children:"The business lesson: AI adoption should compound previous investments"}),"\n",(0,a.jsxs)(n.p,{children:["Milano Software provides business management technology for salons, spas, fitness businesses, retail operations, and other service-based companies. Its public product portfolio covers capabilities such as appointment booking, customer relationship management, point of sale, inventory, reporting, payments, and marketing. Its Klickbook platform extends that experience through a cloud-based booking and business management solution. (",(0,a.jsx)(n.a,{href:"https://milanosoftware.com/",children:"Milano Software"}),", ",(0,a.jsx)(n.a,{href:"https://klickbook.milanosoftware.com/",children:"Klickbook"}),")"]}),"\n",(0,a.jsx)(n.p,{children:"Those capabilities represent more than endpoints."}),"\n",(0,a.jsx)(n.p,{children:"Behind each API operation are years of decisions:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"What information is required to create an appointment?"}),"\n",(0,a.jsx)(n.li,{children:"Which staff members can provide a service?"}),"\n",(0,a.jsx)(n.li,{children:"How should inventory change after a sale?"}),"\n",(0,a.jsx)(n.li,{children:"What happens when a booking is moved or cancelled?"}),"\n",(0,a.jsx)(n.li,{children:"Which customer, payment, or operational rules must always be enforced?"}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"That is where the real value lives."}),"\n",(0,a.jsx)(n.p,{children:'Rebuilding those capabilities in a separate "AI-native" platform would not automatically create more intelligence. It could create duplicated logic, inconsistent behavior, new security boundaries, more systems to operate, and another place where defects can hide.'}),"\n",(0,a.jsx)(n.p,{children:"In business terms, that means more cost, more risk, and a longer road to customer value."}),"\n",(0,a.jsx)(n.p,{children:"The better question is:"}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:"How can an AI application use the trusted capabilities that already exist?"}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"That is the problem HAPI MCP is designed to solve."}),"\n",(0,a.jsx)(n.h2,{id:"what-does-it-mean-to-make-an-api-hapi",children:'What does it mean to make an API "HAPI"?'}),"\n",(0,a.jsx)(n.p,{children:"Making an API HAPI does not mean translating every endpoint into an MCP tool and dropping the entire catalog into an agent\u2019s context."}),"\n",(0,a.jsx)(n.p,{children:"It means creating a controlled AI-facing capability layer over the existing API estate."}),"\n",(0,a.jsxs)(n.p,{children:["MCP is an open standard that connects AI applications with external systems. An MCP server can expose tools that allow a model to retrieve information, invoke an API, or perform an action through a defined schema. (",(0,a.jsx)(n.a,{href:"https://modelcontextprotocol.io/docs/2026-07-28/getting-started/intro",children:"MCP introduction"}),", ",(0,a.jsx)(n.a,{href:"https://modelcontextprotocol.io/specification/2026-07-28/server/tools",children:"MCP tools specification"}),")"]}),"\n",(0,a.jsx)(n.p,{children:"HAPI MCP builds on that model with an API-first principle:"}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"MCP is a contract for AI consumers, not a reason to replace the service behind the contract."})}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The existing API remains the system interface. It continues to serve web applications, mobile applications, integrations, automation, and developers. HAPI MCP adds an interface designed for AI clients and agents."}),"\n",(0,a.jsx)(n.p,{children:"This separation matters because APIs and MCP serve related but different consumers:"}),"\n",(0,a.jsxs)(n.table,{children:[(0,a.jsx)(n.thead,{children:(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.th,{children:"Interface"}),(0,a.jsx)(n.th,{children:"Primary consumers"}),(0,a.jsx)(n.th,{children:"Main concern"})]})}),(0,a.jsxs)(n.tbody,{children:[(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"REST or gRPC API"}),(0,a.jsx)(n.td,{children:"Applications, integrations, developers, automation"}),(0,a.jsx)(n.td,{children:"Predictable programmatic access"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"MCP server"}),(0,a.jsx)(n.td,{children:"AI hosts, assistants, and agents"}),(0,a.jsx)(n.td,{children:"Discoverable, contextual, controlled tool use"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Clawne Me"}),(0,a.jsx)(n.td,{children:"Business users interacting through familiar channels"}),(0,a.jsx)(n.td,{children:"Delegating outcomes without managing AI infrastructure"})]})]})]}),"\n",(0,a.jsx)(n.p,{children:"One does not need to replace the others. They can work as layers of the same architecture."}),"\n",(0,a.jsx)(n.h2,{id:"why-not-expose-every-api-operation-to-the-agent",children:"Why not expose every API operation to the agent?"}),"\n",(0,a.jsx)(n.p,{children:"Milano has many APIs and many possible AI use cases. That creates opportunity, but it also creates an important design challenge."}),"\n",(0,a.jsx)(n.p,{children:"An API catalog is usually organized for software developers. An AI agent does not navigate that catalog the same way a developer does."}),"\n",(0,a.jsx)(n.p,{children:"If hundreds of narrowly defined operations are exposed at once, the model must spend more context and reasoning capacity deciding which tool to use. Similar tools may compete with one another. Tool descriptions become more difficult to distinguish. The probability of selecting the wrong operation, or supplying the wrong arguments, can increase."}),"\n",(0,a.jsx)(n.p,{children:'The shortcut is not "convert everything."'}),"\n",(0,a.jsx)(n.p,{children:"The shortcut is to start with a valuable business intent and expose only the capabilities required to fulfill it."}),"\n",(0,a.jsx)(n.p,{children:"For example, a future scheduling assistant may need to:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsx)(n.li,{children:"Identify a customer."}),"\n",(0,a.jsx)(n.li,{children:"Find eligible services and staff;"}),"\n",(0,a.jsx)(n.li,{children:"check real availability;"}),"\n",(0,a.jsx)(n.li,{children:"create or modify an appointment; and"}),"\n",(0,a.jsx)(n.li,{children:"return a clear confirmation."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The underlying platform may use several API calls to complete that work. The AI consumer should not necessarily be forced to understand every internal step."}),"\n",(0,a.jsx)(n.p,{children:"HAPI MCP can present a smaller, purpose-built tool surface aligned with the user\u2019s intent while allowing Milano\u2019s existing APIs to remain the source of truth."}),"\n",(0,a.jsx)(n.p,{children:"This is context engineering, not merely protocol conversion."}),"\n",(0,a.jsx)(n.h2,{id:"how-does-hapi-mcp-reduce-the-cost-and-risk-of-enterprise-ai-adoption",children:"How does HAPI MCP reduce the cost and risk of enterprise AI adoption?"}),"\n",(0,a.jsx)(n.h3,{id:"1-it-protects-the-investment-already-made-in-apis",children:"1. It protects the investment already made in APIs"}),"\n",(0,a.jsx)(n.p,{children:"Reliable APIs contain proven business logic. Reusing them avoids creating a second implementation that must be developed, tested, secured, documented, monitored, and maintained."}),"\n",(0,a.jsx)(n.p,{children:"The business impact is direct: less duplicated engineering and a shorter path from AI experiment to working capability."}),"\n",(0,a.jsx)(n.h3,{id:"2-it-creates-a-controlled-boundary-for-ai",children:"2. It creates a controlled boundary for AI"}),"\n",(0,a.jsx)(n.p,{children:"An AI model should not receive unrestricted access to every internal operation simply because the API exists."}),"\n",(0,a.jsx)(n.p,{children:"The MCP layer can expose a curated set of tools for a specific role or use case. Teams can decide what the agent is allowed to see, which actions it can request, and which capabilities should remain unavailable."}),"\n",(0,a.jsx)(n.p,{children:"That makes the AI surface deliberate instead of accidental."}),"\n",(0,a.jsx)(n.h3,{id:"3-it-supports-incremental-delivery",children:"3. It supports incremental delivery"}),"\n",(0,a.jsx)(n.p,{children:"Milano does not need to complete every AI use case before delivering the first one."}),"\n",(0,a.jsx)(n.p,{children:"The roadmap can move capability by capability:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"select one meaningful user outcome;"}),"\n",(0,a.jsx)(n.li,{children:"identify the trusted APIs behind it;"}),"\n",(0,a.jsx)(n.li,{children:"expose a focused MCP toolset;"}),"\n",(0,a.jsx)(n.li,{children:"test how agents behave;"}),"\n",(0,a.jsx)(n.li,{children:"validate with real stakeholders; and"}),"\n",(0,a.jsx)(n.li,{children:"expand based on evidence."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Each use case becomes a manageable product decision, not a platform rewrite."}),"\n",(0,a.jsx)(n.h3,{id:"4-it-keeps-deployment-choices-open",children:"4. It keeps deployment choices open"}),"\n",(0,a.jsx)(n.p,{children:"Enterprise software does not live in one universal environment. Some customers use public cloud services. Others require on-premise deployment, hybrid integration, or networks with limited or no external connectivity."}),"\n",(0,a.jsx)(n.p,{children:"HAPI MCP was designed from day zero with these enterprise realities in mind. The MCP layer can run close to the APIs and data it needs to access, including on-premise and air-gapped environments. It can also support public-cloud and hybrid architectures where those models fit the organization."}),"\n",(0,a.jsxs)(n.p,{children:["This is strategically important: ",(0,a.jsx)(n.strong,{children:"AI enablement should not force a customer to abandon its infrastructure, security posture, or data-location requirements."})]}),"\n",(0,a.jsx)(n.h3,{id:"5-it-creates-an-architecture-that-can-evolve",children:"5. It creates an architecture that can evolve"}),"\n",(0,a.jsx)(n.p,{children:"MCP is becoming an important interface for AI applications, but it is still one part of a broader software architecture."}),"\n",(0,a.jsx)(n.p,{children:"Keeping the underlying APIs intact preserves optionality. Milano can serve today\u2019s AI assistants, tomorrow\u2019s agents, conventional applications, partner integrations, and deterministic workflows without betting the entire platform on one interaction model."}),"\n",(0,a.jsx)(n.h2,{id:"why-on-premise-and-air-gapped-ai-matter",children:"Why on-premise and air-gapped AI matter"}),"\n",(0,a.jsx)(n.p,{children:"Public demonstrations of AI often assume three things: the application can reach the internet, the data can leave the environment, and a managed cloud service can be added without friction."}),"\n",(0,a.jsx)(n.p,{children:"Enterprise deployments are not always that simple."}),"\n",(0,a.jsx)(n.p,{children:"An on-premise or air-gapped environment may exist because of privacy obligations, customer contracts, security policy, latency, system dependencies, or operational control. These are not edge cases to dismiss. They are architecture requirements."}),"\n",(0,a.jsx)(n.p,{children:"This changes the AI adoption conversation."}),"\n",(0,a.jsx)(n.p,{children:'The question is no longer only, "Which model should we use?" It becomes:'}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Where will the model run?"}),"\n",(0,a.jsx)(n.li,{children:"Where will the MCP server run?"}),"\n",(0,a.jsx)(n.li,{children:"Can tool execution remain inside the trusted boundary?"}),"\n",(0,a.jsx)(n.li,{children:"How will authentication and authorization be enforced?"}),"\n",(0,a.jsx)(n.li,{children:"What information can enter the model context?"}),"\n",(0,a.jsx)(n.li,{children:"How will actions be logged and reviewed?"}),"\n",(0,a.jsx)(n.li,{children:"Can the solution operate when external services are unavailable?"}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"HAPI MCP cannot make governance decisions on behalf of an enterprise. It can, however, provide an architecture that respects those decisions instead of assuming them away."}),"\n",(0,a.jsx)(n.p,{children:"That distinction is essential for companies like Milano Software, whose platform must work in the environments its customers actually operate."}),"\n",(0,a.jsx)(n.h2,{id:"what-did-milano-software-validate-in-hapi-mcp-08",children:"What did Milano Software validate in HAPI MCP 0.8?"}),"\n",(0,a.jsx)(n.p,{children:"The most valuable product feedback rarely comes from a perfect demo. It comes from applying a product to a real platform with real constraints, numerous APIs, and a roadmap that must produce business value."}),"\n",(0,a.jsx)(n.p,{children:"Through my collaboration with Imran Zalfackruddin, CEO of Milano Software, HAPI MCP 0.8 has benefited from feedback grounded in those realities."}),"\n",(0,a.jsx)(n.p,{children:"The collaboration has reinforced several principles behind HAPI MCP:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Enterprises need a path to AI that builds on their reliable APIs."}),"\n",(0,a.jsx)(n.li,{children:"MCP tools should be organized around use cases and user intent."}),"\n",(0,a.jsx)(n.li,{children:"Large API estates require curation and progressive exposure."}),"\n",(0,a.jsx)(n.li,{children:"On-premise and air-gapped deployment cannot be treated as an afterthought."}),"\n",(0,a.jsx)(n.li,{children:"Cloud, on-premise, and hybrid environments should be architecture choices, not product limitations."}),"\n",(0,a.jsx)(n.li,{children:"Feedback from API owners is as important as feedback from AI developers."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"This validation is meaningful because Milano is not evaluating MCP as an isolated technology experiment. MCP is part of a larger plan to evolve an established software platform toward AI-enabled solutions."}),"\n",(0,a.jsx)(n.p,{children:"That is exactly the environment HAPI MCP is intended to support."}),"\n",(0,a.jsx)(n.h2,{id:"where-does-clawne-me-fit",children:"Where does Clawne Me fit?"}),"\n",(0,a.jsx)(n.p,{children:"HAPI MCP makes trusted software capabilities accessible to AI. Clawne Me focuses on making those AI capabilities accessible to people."}),"\n",(0,a.jsx)(n.p,{children:"This is an important separation."}),"\n",(0,a.jsx)(n.p,{children:"A business owner should not need to understand API paths, JSON schemas, MCP transports, model configuration, or agent infrastructure to ask for an outcome."}),"\n",(0,a.jsx)(n.p,{children:"They should be able to say:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:'"Find open appointment times for Friday afternoon."'}),"\n",(0,a.jsx)(n.li,{children:'"Which products need to be reordered this week?"'}),"\n",(0,a.jsx)(n.li,{children:'"Summarize yesterday\u2019s sales and cancellations."'}),"\n",(0,a.jsx)(n.li,{children:'"Follow up with customers who missed their appointments."'}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The user interacts with a specialized Clawne through a familiar channel. The Clawne interprets the request. HAPI MCP provides the controlled connection to the business capabilities. Milano\u2019s APIs execute the trusted logic."}),"\n",(0,a.jsx)(n.p,{children:"The stack becomes:"}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"People \u2192 Clawne Me \u2192 HAPI MCP \u2192 Milano APIs \u2192 Business systems"})}),"\n",(0,a.jsx)(n.p,{children:"Each layer has a clear responsibility:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Clawne Me"})," simplifies delegation and human\u2013AI interaction."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"HAPI MCP"})," provides the contextual and controlled AI interface."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Milano APIs"})," preserve business logic and reliable execution."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"La Rebelion Labs"})," develops and shares the practical architecture patterns behind this approach."]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Together, they demonstrate a broader idea: enterprise AI becomes more useful when it meets businesses where they already are."}),"\n",(0,a.jsx)(n.h2,{id:"what-should-other-api-first-companies-learn-from-this-collaboration",children:"What should other API-first companies learn from this collaboration?"}),"\n",(0,a.jsx)(n.h3,{id:"do-you-need-to-rebuild-your-platform-to-become-an-ai-company",children:"Do you need to rebuild your platform to become an AI company?"}),"\n",(0,a.jsx)(n.p,{children:"No. In many cases, rebuilding is the slower and riskier path. If the current APIs reliably expose valuable business capabilities, add an AI-facing layer before considering a replacement."}),"\n",(0,a.jsx)(n.h3,{id:"should-every-endpoint-become-an-mcp-tool",children:"Should every endpoint become an MCP tool?"}),"\n",(0,a.jsx)(n.p,{children:"No. Begin with user intent. Expose a focused set of tools required for one outcome, validate agent behavior, and expand deliberately."}),"\n",(0,a.jsx)(n.h3,{id:"is-mcp-only-for-public-cloud-ai",children:"Is MCP only for public-cloud AI?"}),"\n",(0,a.jsxs)(n.p,{children:["No. MCP servers can run locally or remotely. The correct topology depends on security, data, connectivity, and operational requirements. The official MCP architecture explicitly supports local and remote server models. (",(0,a.jsx)(n.a,{href:"https://modelcontextprotocol.io/docs/2026-07-28/learn/architecture",children:"MCP architecture overview"}),")"]}),"\n",(0,a.jsx)(n.h3,{id:"does-mcp-replace-rest-or-grpc",children:"Does MCP replace REST or gRPC?"}),"\n",(0,a.jsx)(n.p,{children:"It should not have to. REST and gRPC remain strong interfaces for applications and developers. MCP provides a complementary contract designed for AI consumers."}),"\n",(0,a.jsx)(n.h3,{id:"what-is-the-best-first-ai-use-case",children:"What is the best first AI use case?"}),"\n",(0,a.jsx)(n.p,{children:"Choose a task that is valuable, bounded, measurable, and already supported by reliable APIs. Avoid beginning with the largest possible autonomous agent. Start with a capability where success and failure are easy to observe."}),"\n",(0,a.jsx)(n.h2,{id:"the-bigger-idea-preserve-reliability-while-changing-the-interface",children:"The bigger idea: preserve reliability while changing the interface"}),"\n",(0,a.jsx)(n.p,{children:"AI changes how people can interact with software. It does not erase the need for trusted business logic, security, predictable execution, observability, or operational discipline."}),"\n",(0,a.jsx)(n.p,{children:"That is why Milano Software\u2019s approach matters."}),"\n",(0,a.jsx)(n.p,{children:"The company is not treating its existing platform as technical debt that must be discarded before AI can begin. It is treating its APIs as strategic assets that can be made available to a new class of consumer."}),"\n",(0,a.jsx)(n.p,{children:"HAPI MCP provides the shortcut, not by skipping architecture, but by avoiding unnecessary reinvention."}),"\n",(0,a.jsx)(n.p,{children:"There is still serious work ahead. Milano has many APIs and use cases on its roadmap. Each capability must be designed, scoped, secured, tested, and validated. But the path is now clearer:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsx)(n.li,{children:"Keep the reliable platform."}),"\n",(0,a.jsx)(n.li,{children:"Select the business outcome."}),"\n",(0,a.jsx)(n.li,{children:"Curate the required API capabilities."}),"\n",(0,a.jsx)(n.li,{children:"Expose them through HAPI MCP."}),"\n",(0,a.jsx)(n.li,{children:"Connect them to the right AI experience."}),"\n",(0,a.jsx)(n.li,{children:"Learn, validate, and expand."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"That is a more responsible way to accelerate AI adoption, and a more sustainable way to become an AI-enabled software company."}),"\n",(0,a.jsx)(n.h2,{id:"thank-you-milano-software-and-imran",children:"Thank you, Milano Software and Imran"}),"\n",(0,a.jsxs)(n.p,{children:["I want to thank ",(0,a.jsx)(n.strong,{children:"Milano Software"})," and ",(0,a.jsx)(n.strong,{children:"Imran Zalfackruddin"})," for the feedback, practical challenges, and validation they have contributed to HAPI MCP 0.8."]}),"\n",(0,a.jsx)(n.p,{children:"Building an enterprise-ready product requires more than implementing a protocol. It requires listening to organizations that have reliable platforms, real customers, demanding environments, and meaningful AI roadmaps."}),"\n",(0,a.jsx)(n.p,{children:"This collaboration is helping HAPI MCP become stronger for on-premise, air-gapped, hybrid, and public-cloud use cases."}),"\n",(0,a.jsx)(n.p,{children:"And it confirms the principle that started this work:"}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"Your APIs do not need to be replaced to participate in the AI era. They need the right interface for AI."})}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"That is how we make APIs HAPI."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"suggested-seo-metadata",children:"Suggested SEO metadata"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"SEO title:"})," Milano Software Accelerates Enterprise AI Adoption with HAPI MCP"]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Meta description:"})," Learn how Milano Software is using HAPI MCP to connect reliable enterprise APIs with AI across on-premise, air-gapped, hybrid, and cloud environments, without rebuilding its proven platform."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Primary keyword:"})," enterprise AI adoption with HAPI MCP"]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Secondary keywords:"})," API to MCP, enterprise MCP server, on-premise MCP, air-gapped AI, Milano Software AI, Model Context Protocol, Clawne Me, La Rebelion Labs"]}),"\n",(0,a.jsx)(n.h2,{id:"suggested-linkedin-post",children:"Suggested LinkedIn post"}),"\n",(0,a.jsx)(n.p,{children:"The fastest path to enterprise AI may be the platform you already have."}),"\n",(0,a.jsx)(n.p,{children:"Milano Software has spent years building reliable APIs around real business operations: appointments, customers, inventory, payments, reporting, and more."}),"\n",(0,a.jsx)(n.p,{children:'Rebuilding that platform "for AI" would duplicate logic, add risk, and delay value.'}),"\n",(0,a.jsx)(n.p,{children:"Our collaboration is exploring a better path: preserve the APIs and make selected capabilities available to AI through HAPI MCP."}),"\n",(0,a.jsx)(n.p,{children:"This work has provided valuable feedback and real-world validation for HAPI MCP 0.8, especially for on-premise and air-gapped environments. Public cloud and hybrid deployments remain options, but they should be choices, not requirements."}),"\n",(0,a.jsx)(n.p,{children:"Thank you to Milano Software and Imran Zalfackruddin for helping us test the principle behind HAPI MCP:"}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"Your APIs do not need to be replaced to participate in the AI era. They need the right interface for AI."})}),"\n",(0,a.jsx)(n.p,{children:"That is how we make APIs HAPI."}),"\n",(0,a.jsx)(n.p,{children:"#HAPIMCP #ModelContextProtocol #EnterpriseAI #APIs #AgenticAI #ClawneMe #LaRebelionLabs"})]})}function h(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}}}]);